import unittest
from triage import authorized,triage,timeline
class TriageTests(unittest.TestCase):
    def test_allow_read(self):self.assertTrue(authorized('analyst','read_redacted'))
    def test_deny_action(self):self.assertFalse(authorized('analyst','propose_containment'))
    def test_unknown_role_denied(self):self.assertFalse(authorized('unknown','read_redacted'))
    def test_threshold_is_not_verdict(self):
        result=triage([{'actor_alias':'actor-a','outcome':'failed'}]*3)
        self.assertEqual(result,[{'actor_alias':'actor-a','failed_count':3,'disposition':'investigate'}])
    def test_below_threshold(self):self.assertEqual(triage([{'actor_alias':'actor-a','outcome':'failed'}]*2),[])
    def test_timezone_normalization(self):
        events=[{'id':'later','time':'2026-01-01T12:00:00Z'},{'id':'earlier','time':'2026-01-01T12:30:00+01:00'}]
        self.assertEqual(timeline(events)[0]['id'],'earlier')
    def test_missing_timezone_rejected(self):
        with self.assertRaises(ValueError):timeline([{'time':'2026-01-01T12:00:00'}])
if __name__=='__main__':unittest.main()

"""Local, fictional SOC analysis. No scanning, account changes or real logs."""
from datetime import datetime, timezone

POLICY={'analyst':{'read_redacted'},'responder':{'read_redacted','propose_containment'}}
def authorized(role, action):
    return action in POLICY.get(role,set())

def triage(events, threshold=3):
    if type(threshold) is not int or threshold<1: raise ValueError('Positive integer threshold required')
    counts={}
    for event in events:
        # This is a count rule, not an inference about an attack or a person.
        if event.get('outcome')=='failed':
            actor=event.get('actor_alias')
            if not isinstance(actor,str) or not actor: raise ValueError('Fictional actor alias required')
            counts[actor]=counts.get(actor,0)+1
    return [{'actor_alias':a,'failed_count':n,'disposition':'investigate'} for a,n in sorted(counts.items()) if n>=threshold]

def timeline(events):
    def time_of(event):
        value=datetime.fromisoformat(event['time'].replace('Z','+00:00'))
        if value.tzinfo is None:raise ValueError('Explicit timezone required')
        return value.astimezone(timezone.utc)
    return sorted(events,key=time_of)
